appendLink(target, label, title) {
        this.value += '[';
        this.value += this.c(label, ']');
        this.value += '](';
        this.value += this.c(String(target), ')');
        if (title) {
            this.value += ` "${this.c(this.c(title, '"'), ')')}"`;
        }
        this.value += ')';
        return this;
    }
